class CSurveillanceCameraEntity:public CBaseAnimating{DECLARE_CLASS(CSurveillanceCameraEntity,CBaseAnimating);public:void Spawn()override{pev->movetype=MOVETYPE_NONE;pev->solid=SOLID_BBOX;pev->takedamage=DAMAGE_YES;pev->health=10.0f;SET_MODEL(edict(),"models/weapon/Camera/w_camera.mdl");pev->frame=0;pev->framerate=0;ResetSequenceInfo();UTIL_SetSize(pev,Vector(-8,-8,-8),Vector(8,8,8));SetBits(pev->effects,EF_NOINTERP|EF_MERGE_VISIBILITY);}void Killed(entvars_t*pevAttacker,int iGib)override{UTIL_Sparks(GetAbsOrigin());EMIT_SOUND(edict(),CHAN_BODY,"buttons/spark5.wav",1.0f,ATTN_NORM);CBasePlayer*owner=pev->euser1?static_cast<CBasePlayer*>(CBaseEntity::Instance(pev->euser1)):nullptr;if(owner&&owner->m_pActiveItem&&owner->m_pActiveItem->iWeaponID()==WEAPON_SURVEILLANCE_CAMERA)static_cast<CSurveillanceCamera*>(owner->m_pActiveItem)->OnCameraDestroyed(this);CBaseEntity*view=CBaseEntity::Instance(pev->euser2);if(view)UTIL_Remove(view);UTIL_Remove(this);}};
